import{_ as a,o as t,c as n,a5 as s}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"HJ67 24点游戏算法","description":"中等 通过率：33.13% 时间限制：1秒 空间限制：32M 知识点 dfs 搜索 描述 给出4个1 10的数字，通过加减乘除运算，得到数字为24就算胜利,除法指实数除法运算,运算符仅允许出现在两个数字之间,本题对数字选取顺序无要求，但每个数字仅允许使用一次，且需考虑括号运算 此。","frontmatter":{"title":"HJ67 24点游戏算法","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"中等 通过率：33.13% 时间限制：1秒 空间限制：32M 知识点 dfs 搜索 描述 给出4个1 10的数字，通过加减乘除运算，得到数字为24就算胜利,除法指实数除法运算,运算符仅允许出现在两个数字之间,本题对数字选取顺序无要求，但每个数字仅允许使用一次，且需考虑括号运算 此。","sidebarWeight":21,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/动态规划【中等】/HJ67 24点游戏算法.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/动态规划【中等】/HJ67 24点游戏算法.md","filePath":"posts/前端面试与实战/03-算法训练/动态规划【中等】/HJ67 24点游戏算法.md"}'),o={name:"posts/前端面试与实战/03-算法训练/动态规划【中等】/HJ67 24点游戏算法.md"};function r(i,e,l,d,u,c){return t(),n("div",null,[...e[0]||(e[0]=[s('<div><h1 id="hj67-24点游戏算法" tabindex="-1">HJ67 24点游戏算法 <a class="header-anchor" href="#hj67-24点游戏算法" aria-label="Permalink to &quot;HJ67 24点游戏算法&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ67 24点游戏算法”的核心思路，并能把它用于实际开发或面试表达。 中等 通过率：33.13% 时间限制：1秒 空间限制：32M 知识点==dfs====搜索== <strong>描述</strong> 给出4个1-10的数字，通过加减乘除运算，得到数字为24就算胜利,除法指实数除法运算,运算符仅允许出现在两个数字之间,本题对数字选取顺序无要求，但每个数字仅允许使用一次，且需考虑括号运算</p></blockquote><p>此题允许数字重复，如3 3 4 4为合法输入，此输入一共有两个3，但是每个数字只允许使用一次，则运算过程中两个3都被选取并进行对应的计算操作。 <strong>输入描述：</strong> 读入4个[1,10]的整数，数字允许重复，测试用例保证无异常数字。 <strong>输出描述：</strong> 对于每组案例，输出一行表示能否得到24点，能输出true，不能输出false <strong>示例1</strong> 输入： 7 2 1 10 ==复制== 输出： true</p><p>解决这个问题的方法之一是使用深度优先搜索（DFS）。思路是尝试所有可能的数字组合和所有可能的运算符组合，检查是否能得到24。这里是具体的步骤：</p><ol><li><strong>选择操作数</strong>：从剩下的数字中选择两个数字，有 $\\frac{n(n-1)}{2}$ 种选择方法（$n$是当前剩余的数字数量）。</li><li><strong>选择运算符</strong>：对于每一对选择的数字，尝试所有四种运算（加、减、乘、除）。注意，减法和除法是不对称的，所以每种操作都有两种不同的顺序（比如$a-b$和$b-a$）。</li><li><strong>递归</strong>：每次操作后，将操作结果加入到数字集合中，并从集合中移除被操作的两个数字，然后递归地进行下一步搜索。</li><li><strong>终止条件</strong>：当数字集合中只剩下一个数字时，检查这个数字是否为24（或在某个很小的误差范围内，考虑到浮点数的精度问题）。</li></ol><p>以下是基于这个思路的Python代码实现： def solve(nums): if len(nums) == 1:</p><h1 id="考虑到浮点数的精度问题-这里使用一个小的误差范围来判断是否等于24" tabindex="-1">考虑到浮点数的精度问题，这里使用一个小的误差范围来判断是否等于24 <a class="header-anchor" href="#考虑到浮点数的精度问题-这里使用一个小的误差范围来判断是否等于24" aria-label="Permalink to &quot;考虑到浮点数的精度问题，这里使用一个小的误差范围来判断是否等于24&quot;">​</a></h1><p>return abs(nums[0] - 24) &lt; 1e-6</p><h1 id="尝试所有可能的数字组合" tabindex="-1">尝试所有可能的数字组合 <a class="header-anchor" href="#尝试所有可能的数字组合" aria-label="Permalink to &quot;尝试所有可能的数字组合&quot;">​</a></h1><p>for i in range(len(nums)): for j in range(len(nums)): if i != j:</p><h1 id="对于每一对数字-尝试所有可能的运算" tabindex="-1">对于每一对数字，尝试所有可能的运算 <a class="header-anchor" href="#对于每一对数字-尝试所有可能的运算" aria-label="Permalink to &quot;对于每一对数字，尝试所有可能的运算&quot;">​</a></h1><p>next_nums = [nums[k] for k in range(len(nums)) if i != k != j] a, b = nums[i], nums[j] candidates = set([a+b, a-b, b-a, a*b]) if b: candidates.add(a / b) if a: candidates.add(b / a) for n in candidates: if solve(next_nums + [n]): return True return False</p><h1 id="输入四个数字" tabindex="-1">输入四个数字 <a class="header-anchor" href="#输入四个数字" aria-label="Permalink to &quot;输入四个数字&quot;">​</a></h1><p>nums = list(map(int, input().split()))</p><h1 id="输出是否可以通过运算得到24" tabindex="-1">输出是否可以通过运算得到24 <a class="header-anchor" href="#输出是否可以通过运算得到24" aria-label="Permalink to &quot;输出是否可以通过运算得到24&quot;">​</a></h1><p>print(&#39;true&#39; if solve(nums) else &#39;false&#39;)</p><p>这段代码首先定义了一个递归函数<code>solve</code>，用于检查给定的数字列表是否能通过运算得到24。对于每一对数字，它尝试所有可能的运算，并递归地检查剩余数字加上运算结果是否能得到24。当数字列表只剩下一个数字时，它检查这个数字是否为24，以确定是否找到了解决方案。最后，根据<code>solve</code>函数的返回值输出结果。</p></div>',1)])])}const f=a(o,[["render",r]]);export{h as __pageData,f as default};
